"""Generate src/icons.generated.ts from figtree.icons.ICONS so the React package and the Python
generator share one icon family (24x24 grid, stroke 2, currentColor, no fill)."""
from __future__ import annotations

import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))
from figtree.icons import ICONS, ICON_VIEWBOX  # noqa: E402

out = pathlib.Path(__file__).resolve().parents[1] / "src" / "icons.generated.ts"
lines = [
    "// Generated by scripts/gen_icons.py from figtree/icons.py. Do not edit by hand.",
    f"export const ICON_VIEWBOX = {ICON_VIEWBOX!r};",
    "",
    "/** Inner SVG markup of every icon in the FigTree family (24x24, stroke 2, currentColor). */",
    "export const ICON_PATHS = {",
]
for name in sorted(ICONS):
    lines.append(f"  {name!r}: {ICONS[name]!r},")
lines += [
    "} as const;",
    "",
    "export type IconName = keyof typeof ICON_PATHS;",
    "export const ICON_NAMES = Object.keys(ICON_PATHS) as IconName[];",
    "",
]
out.write_text("\n".join(lines).replace("'", '"', 0))
print(f"wrote {out} ({len(ICONS)} icons)")
